INSERT INTO it_glossary (term_ja, reading, term_ko, term_en, category, description, example_sentence) VALUES
  ('暗号化', 'あんごうか', '암호화', 'Encryption', 'infrastructure', '데이터를 제3자가 읽을 수 없도록 특정 규칙에 따라 변환하는 기술입니다. 개인정보나 기밀 데이터를 보호하기 위해 사용됩니다.', '個人情報を送信する際は必ず暗号化を行ってください。'),
  ('復号', 'ふくごう', '복호화', 'Decryption', 'infrastructure', '암호화된 데이터를 원래의 읽을 수 있는 형태로 되돌리는 과정입니다.', '受信したデータを復号してから内容を確認します。'),
  ('マルウェア', 'マルウェア', '멀웨어', 'Malware', 'infrastructure', '컴퓨터에 피해를 주기 위해 만들어진 악성 소프트웨어의 총칭입니다. 바이러스, 웜, 트로이목마 등이 포함됩니다.', 'マルウェア対策ソフトを最新の状態に保ってください。'),
  ('ランサムウェア', 'ランサムウェア', '랜섬웨어', 'Ransomware', 'infrastructure', '컴퓨터의 파일을 암호화하여 사용할 수 없게 만든 뒤 돈을 요구하는 악성 프로그램입니다.', 'ランサムウェアの被害を防ぐため、定期的にバックアップを取ってください。'),
  ('フィッシング', 'フィッシング', '피싱', 'Phishing', 'infrastructure', '신뢰할 수 있는 기관을 사칭하여 개인정보를 빼내는 사기 수법입니다. 주로 이메일이나 가짜 웹사이트를 이용합니다.', 'フィッシングメールに注意して、不審なリンクをクリックしないでください。'),
  ('二要素認証', 'にようそにんしょう', '이중 인증', 'Two-Factor Authentication', 'infrastructure', '비밀번호 외에 한 가지 추가 인증 수단을 사용하여 보안을 강화하는 방법입니다.', '社内システムには二要素認証を設定してください。'),
  ('多要素認証', 'たようそにんしょう', '다중 인증', 'Multi-Factor Authentication', 'infrastructure', '두 가지 이상의 서로 다른 인증 수단을 조합하여 본인 확인을 하는 보안 방식입니다.', 'セキュリティ強化のため多要素認証を導入しました。'),
  ('不正アクセス', 'ふせいあくせす', '불법 접근', 'Unauthorized Access', 'infrastructure', '허가 없이 타인의 컴퓨터나 시스템에 침입하는 행위입니다. 법률로 금지되어 있습니다.', '不正アクセスを検知した場合は直ちに報告してください。'),
  ('脆弱性', 'ぜいじゃくせい', '취약점', 'Vulnerability', 'infrastructure', '소프트웨어나 시스템의 보안상 약점으로, 공격자에게 악용될 수 있는 결함입니다.', '脆弱性診断を実施してセキュリティリスクを洗い出します。'),
  ('セキュリティポリシー', 'セキュリティポリシー', '보안 정책', 'Security Policy', 'infrastructure', '조직의 정보 보안에 관한 기본 방침과 규칙을 정리한 문서입니다.', 'セキュリティポリシーに従ってパスワードを管理してください。'),
  ('情報セキュリティ', 'じょうほうせきゅりてぃ', '정보 보안', 'Information Security', 'infrastructure', '정보의 기밀성, 완전성, 가용성을 보호하기 위한 활동과 기술의 총칭입니다.', '情報セキュリティ研修を全社員に実施しています。'),
  ('機密性', 'きみつせい', '기밀성', 'Confidentiality', 'infrastructure', '허가된 사람만 정보에 접근할 수 있도록 보호하는 성질입니다. 정보 보안의 3요소 중 하나입니다.', '機密性を確保するためにアクセス権限を適切に設定してください。'),
  ('完全性', 'かんぜんせい', '무결성', 'Integrity', 'infrastructure', '정보가 허가 없이 변경되거나 파괴되지 않도록 보호하는 성질입니다. 정보 보안의 3요소 중 하나입니다.', 'データの完全性を保つためにチェックサムを使用しています。'),
  ('リスクアセスメント', 'リスクアセスメント', '리스크 평가', 'Risk Assessment', 'infrastructure', '잠재적인 위험을 식별하고 그 영향과 발생 가능성을 평가하는 과정입니다.', 'リスクアセスメントを行い、優先的に対応すべき脅威を特定しました。'),
  ('バイオメトリクス認証', 'バイオメトリクスにんしょう', '생체 인증', 'Biometric Authentication', 'infrastructure', '지문, 얼굴, 홍채 등 신체 특징을 이용하여 본인을 확인하는 인증 방식입니다.', 'オフィスの入退室にバイオメトリクス認証を導入しました。'),
  ('デジタル署名', 'デジタルしょめい', '디지털 서명', 'Digital Signature', 'infrastructure', '전자 문서의 작성자와 내용이 변경되지 않았음을 증명하는 전자적 서명입니다.', 'デジタル署名を付与して文書の真正性を保証します。'),
  ('公開鍵暗号', 'こうかいかぎあんごう', '공개키 암호', 'Public Key Cryptography', 'infrastructure', '암호화와 복호화에 서로 다른 키(공개키와 비밀키)를 사용하는 암호 방식입니다.', '公開鍵暗号を使ってセキュアな通信を実現しています。'),
  ('共通鍵暗号', 'きょうつうかぎあんごう', '공통키 암호', 'Symmetric Key Cryptography', 'infrastructure', '암호화와 복호화에 동일한 키를 사용하는 암호 방식입니다. 처리 속도가 빠른 것이 장점입니다.', '共通鍵暗号はデータの暗号化速度が速いため、大量データの処理に適しています。'),
  ('WAF', 'ワフ', 'WAF', 'Web Application Firewall', 'infrastructure', '웹 애플리케이션에 대한 공격을 탐지하고 차단하는 전문 방화벽입니다.', 'WAFを導入してWebアプリケーションへの攻撃を防御しています。'),
  ('IDS', 'アイディーエス', 'IDS', 'Intrusion Detection System', 'infrastructure', '네트워크나 시스템에 대한 불법 침입을 탐지하는 시스템입니다.', 'IDSが不審な通信パターンを検知しました。'),
  ('IPS', 'アイピーエス', 'IPS', 'Intrusion Prevention System', 'infrastructure', '불법 침입을 탐지할 뿐만 아니라 자동으로 차단까지 수행하는 시스템입니다.', 'IPSを導入して不正アクセスをリアルタイムで遮断しています。'),
  ('ペネトレーションテスト', 'ペネトレーションテスト', '모의 침투 테스트', 'Penetration Test', 'infrastructure', '실제 해커의 공격을 모방하여 시스템의 보안 취약점을 찾아내는 테스트입니다.', 'リリース前にペネトレーションテストを実施してセキュリティを確認します。'),
  ('SQLインジェクション', 'エスキューエルインジェクション', 'SQL 인젝션', 'SQL Injection', 'infrastructure', '웹 애플리케이션의 입력란에 악의적인 SQL 코드를 삽입하여 데이터베이스를 조작하는 공격입니다.', 'SQLインジェクション対策としてプリペアドステートメントを使用してください。'),
  ('クロスサイトスクリプティング', 'クロスサイトスクリプティング', '크로스 사이트 스크립팅', 'Cross-Site Scripting', 'infrastructure', '웹사이트에 악성 스크립트를 삽입하여 사용자의 정보를 탈취하는 공격 기법입니다.', 'クロスサイトスクリプティングを防ぐために入力値のサニタイズを行ってください。'),
  ('DDoS攻撃', 'ディードスこうげき', 'DDoS 공격', 'DDoS Attack', 'infrastructure', '다수의 컴퓨터에서 동시에 대량의 요청을 보내 서버를 마비시키는 공격입니다.', 'DDoS攻撃に備えてCDNとWAFの対策を強化しました。'),
  ('ゼロデイ攻撃', 'ゼロデイこうげき', '제로데이 공격', 'Zero-Day Attack', 'infrastructure', '소프트웨어의 보안 취약점이 발견된 후 수정 패치가 나오기 전에 그 취약점을 악용하는 공격입니다.', 'ゼロデイ攻撃のリスクを最小限にするためソフトウェアを常に最新に保ちましょう。'),
  ('パスワードポリシー', 'パスワードポリシー', '비밀번호 정책', 'Password Policy', 'infrastructure', '비밀번호의 길이, 복잡도, 변경 주기 등에 관한 규칙입니다.', 'パスワードポリシーに従い、8文字以上の英数字記号を含むパスワードを設定してください。'),
  ('アクセス制御', 'アクセスせいぎょ', '접근 제어', 'Access Control', 'infrastructure', '시스템이나 데이터에 대한 접근 권한을 관리하고 통제하는 것입니다.', 'アクセス制御を適切に設定して、必要な権限のみ付与してください。'),
  ('情報漏洩', 'じょうほうろうえい', '정보 유출', 'Information Leakage', 'infrastructure', '기밀 정보나 개인정보가 외부에 유출되는 사고입니다. 기업에 큰 피해를 줄 수 있습니다.', '情報漏洩を防ぐため、USBメモリの使用を制限しています。'),
  ('監査ログ', 'かんさろぐ', '감사 로그', 'Audit Log', 'infrastructure', '시스템에서 누가 언제 어떤 작업을 했는지 기록한 로그입니다. 보안 사고 조사에 필수적입니다.', '監査ログを定期的に確認して不審な操作がないか監視しています。'),
  ('インシデント対応', 'インシデントたいおう', '인시던트 대응', 'Incident Response', 'infrastructure', '보안 사고가 발생했을 때 피해를 최소화하기 위해 신속하게 대처하는 절차입니다.', 'インシデント対応マニュアルに従って迅速に対処してください。'),
  ('BCP', 'ビーシーピー', 'BCP', 'Business Continuity Plan', 'infrastructure', '재해나 사고 발생 시에도 사업을 지속하기 위한 계획입니다.', 'BCPを策定して、災害時の業務継続体制を整備しました。'),
  ('ディザスタリカバリ', 'ディザスタリカバリ', '재해 복구', 'Disaster Recovery', 'infrastructure', '재해로 인한 시스템 장애 시 정상 상태로 복구하기 위한 계획과 절차입니다.', 'ディザスタリカバリの訓練を年に一度実施しています。')
